#!/usr/bin/env bash\nset -euo pipefail\n\nusage() {\n  echo "Usage: $0 [directory] [count]"\n  exit 1\n}\n\n# Default arguments\nTARGET="${1:-.}"\nCOUNT="${2:-5}"\nMAX_BAR=40\n\n# Gather sizes in kilobytes, sort descending, keep top $COUNT\nmapfile -t lines < <(du -k --max-depth=1 "$TARGET"/* 2>/dev/null | sort -hr | head -n "$COUNT")\n\n# Determine the maximum size for scaling the bars\nmax_size=0\nfor line in "${lines[@]}"; do\n  size=${line%%[[:space:]]*}\n  (( size > max_size )) && max_size=$size\n done\n\n# Print the chart\nfor line in "${lines[@]}"; do\n  size=${line%%[[:space:]]*}\n  name=${line#*[[:space:]]}\n  # Compute bar length proportionally (at least 1 char)\n  if (( max_size == 0 )); then\n    bar_len=0\n  else\n    bar_len=$(( size * MAX_BAR / max_size ))\n    (( bar_len == 0 )) && bar_len=1\n  fi\n  bar=$(printf "%${bar_len}s" "" | tr " " "#")\n  printf "%-20s %6sK %s\n" "$(basename \"$name\")" "$size" "$bar"\n done\n
